{v:'VER',what:'a Magnum shot kicks the camera 5.5, up from 4.5 (about 2.8 px), and six shots at full rate never stack past 3.4 px (his Q5 gun feel)',
 run:function(){
   if(typeof gunShake!=='function'||typeof gfxTrauma!=='function') return 'SKIP: no gunShake';
   var g=null;
   try{
     __runPrep(); __topClear(); __resetCfg(); __pinDefaults(0); __cleanProfile();
     __deploy({kit:[],safe:null,mapIx:0,seed:4242});
     g=__state(); if(!g||!g.player) return 'SKIP: no raid';
     var w=WEAPONS.magnum, mx=0, i, nx=0, t=0, dt=1/60, n=0, one=-1;
     CFG.shake=1; CFG.fxInt=1; GFX.shG=null; G.shake=0; gfxTrauma(dt);
     for(i=0;i<420;i++){
       t+=dt;
       if(t>=nx&&n<6){ G.shake=0; fireWeapon(g.player,w,g.player.x+200,g.player.y,true); if(n===0) one=G.shake; nx+=w.rof/1000; n++; }
       gfxTrauma(dt); if(GFX.shA>mx) mx=GFX.shA;
       if(G.shake>0) G.shake=Math.max(0,G.shake-dt*26);
     }
     if(Math.abs(one-5.5)>0.01) return 'a Magnum shot sets a kick of '+one+', not 5.5';
     if(!(mx>2.3)) return 'six Magnum shots shake the camera only '+mx.toFixed(2)+' px, under 2.3';
     if(!(mx<3.4)) return 'six Magnum shots shake the camera '+mx.toFixed(2)+' px, over 3.4';
     return null;
   } finally {
     try{ __endRaid('abandon'); }catch(_e){}
     __topClear();
   } }},
